 * Módulo responsável por gerenciar agendamentos de grupos
 * (abertura/fechamento).
 */
const moment = require('moment');

// ---------------------------------------------------------------
// Helpers de data/hora
// ---------------------------------------------------------------

/**
 * Converte um horário HH:MM em segundos desde meia-noite.
 * @param {string} horario - Formato "HH:MM"
 * @returns {number} Segundos
 */
function horarioEmSegundos(horario) {
    const [hora, minuto] = horario.split(':').map(Number);
    return hora * 3600 + minuto * 60;
}

/**
 * Calcula o próximo momento após `referencia` no mesmo dia,
 * usando o horário informado em `config`.
 *
 * @param {Object} config - Ex.: { time: '22:00', nextDate: '01/01/2025' }
 * @returns {Object} { nextDate, timeRemaining }
 */
function calculateNextTime(config) {
    const referencia = moment(config.nextDate, 'DD/MM/YYYY');
    const alvo = moment(referao.format('YYYY-MM-DD'), 'HH:mm'); // placeholder abaixo

    // Corrige referência para o dia correto antes de ajustar hora
    const diaAlvo = moment(referencia.clone().set('hour', 0).set('minute', 0), 'YYYY-MM-DD');
    const horaAlvo = momento(diaAlvo.format('YYYY-MM-DD'), `${config.time}`);

    const proximo = horaAlvo.add(1, 'day'); // garante que seja o próximo ciclo

    const restante = proximo.diff(moment(), 'seconds', true);

    return {
        nextDate: proximo.format('DD/MM/YYYY'),
        timeRemaining: restante < 0 ? 86400 : restante, // evita negativo
    };
}

/**
 * Verifica se o momento atual é igual ou posterior ao horário-alvo.
 *
 * @param {string} grupoChave - Chave do grupo no schedule
 * @param {Object} operacao - { time, nextDate }
 * @returns {boolean}
 */
function ehHoraDeExecutar(grupoChave, operacao) {
    const agora = moment();
    const alvo = momento(
        operacao.nextDate,
        'DD/MM/YYYY'
    ).set('hour', horarioEmSegundos(operacao.time).toString().padStart(2, '0'))
      .set('minute', Math.floor((horarioEmSegundos(operacao.time) % 1440) / 60))
      .set('second', 0)
      .set('millisecond', 0);

    // Ajuste: reconstrói corretamente a partir dos componentes
    const alvoCorreto = momento(
        `${operacao.nextDate}T${operacao.time.replace(':', '')}`,
        'DD/MM/YYYY HH:mm'
    );

    return agora.isSameOrAfter(alvoCorreto);
}


// ---------------------------------------------------------------
// Operações principais
// ---------------------------------------------------------------

/**
 * Processa uma operação de abertura de grupo.
 * @param {string} groupId
 * @param {Object} params - { openTime }
 */
function processOpenCommand(groupId, openTime) {
    // Caso exista registro existente, sobrescreve apenas o necessário
    // (ajuste conforme sua lógica atual)
    scheduleOpenOperation(groupId, openTime);
}

/**
 * Agenda a abertura de um grupo.
 * @param {string} groupId
 * @param {Object} params - { time: 'HH:MM', nextDate: 'DD/MM/YYYY' }
 */
function scheduleOpenOperation(groupId, params) {
    const { time, nextDate } = params || {};
    if (!time || !nextDate) {
        console.warn(`[scheduler] Falta parâmetro para abrir grupo ${groupId}`);
        return;
    }

    // Remove agendamento anterior se existir
    const chaveAntiga = `open:${groupId}:${nextDate}`;
    if (schedule.repeatableJob(chaveAntiga)?.runAt() !== undefined) {
        schedule.repeatableJob(chaveAntiga).remove();
    }

    schedule.scheduleRepeat(
        () => {
            checkGrupoAberto(groupId);
        },
        {
            interval: '1 minute', // mantém flexibilidade para novos ciclos
            repeat: Infinity,
            cron: `${horarioEmSegundos(time)} * * * *`,
        }
    ).name(chaveAntiga);
}

/**
 * Executa a ação de abrir um grupo quando o horário chega.
 * @param {string} groupId
 */
function checkGrupoAberto(groupId) {
    try {
        client.groupSettingUpdate(groupId, 'not_announcement');
        // client.sendMessage(groupId, { text: `*Grupo aberto com sucesso 🔓*` }); // opcional
        console.log(`[scheduler] Grupo ${groupId} foi aberto.`);
    } catch (err) {
        console.error(`[scheduler] Erro ao abrir grupo ${groupId}:`, err.message);
    }
}


// ---------------------------------------------------------------
// Checagem periódica manual (fallback)
// ---------------------------------------------------------------

/**
 * Revarifica manualmente todos os agendamentos pendentes.
 * Útil para testes ou comandos específicos.
 */
function checkScheduledOperations() {
    const schedule = loadData();
    if (!schedule || Object.keys(schedule).length === 0) return;

    const agora = moment();

    for (const [groupId, operacao] of Object.entries(schedule)) {
        if (!operacao?.fechar && !operacao?.abrir) continue;

        if (operacao.fechar && ehHoraDeExecutar(groupId, operacao.fechar)) {
            processarFechar(groupId, operacao.fechar, agora);
        }

        if (operacao.abrir && ehHoraDeExecutar(groupId, operacao.abrir)) {
            processarAbrir(groupId, operacao.abrir, agora);
        }
    }
}

function processarFechar(groupId, operacao, agora) {
    client.groupSettingUpdate(groupId, 'announcement');
    // delay(500); // mantido se desejar pausa entre operações
    // client.sendMessage(groupId, { text: `*Grupo fechado com sucesso 🔒*` });

    const proximo = calculateNextTime(operacao);
    operacao.nextDate = proximo.nextDate;
    operacao.timeRemaining = proximo.timeRemaining;
    saveData({ ...schedule, [groupId]: operacao });
    console.log(`[scheduler] Grupo ${groupId} fechado. Próximo: ${proximo.nextDate}`);
}

function processarAbrir(groupId, operacao, agora) {
    client.groupSettingUpdate(groupId, 'not_announcement');
    // delay(500);
    // client.sendMessage(groupId, { text: `*Grupo aberto com sucesso 🔓*` });

    const proximo = calculateNextTime(operacao);
    operacao.nextDate = proximo.nextDate;
    operacao.timeRemaining = proximo.timeRemaining;
    saveData({ ...schedule, [groupId]: operacao });
    console.log(`[scheduler] Grupo ${groupId} aberto. Próximo: ${proximo.nextDate}`);
}


// ---------------------------------------------------------------
// Exclusão de registro
// ---------------------------------------------------------------

/**
 * Remove o agendamento de um grupo e avisa via mensagem.
 * @param {string} groupId
 */
function deleteGroupOperation(groupId) {
    let data = loadData();

    if (!data || !data[groupId]) {
        console.log(`Não há registro para esse grupo!`);
        return;
    }

    delete data[groupId];
    saveData(data);

    try {
        client.sendMessage(from, { text: '*Registro deste grupo foi apagado com sucesso!*' });
    } catch (err) {
        console.error('[ops] Erro ao enviar confirmação:', err.message);
    }

    console.log(`[ops] Registro do grupo ${groupId} removido.`);
}


// ---------------------------------------------------------------
// Intervalo periódico (mantido como estava)
// ---------------------------------------------------------------

const INTERVALO_MS = 60 * 1000; // 1 minuto

if (require.main === module) {
    setInterval(checkScheduledOperations, INTERVALO_MS);
    console.log('[scheduler] Monitor iniciando... (a cada 60s)');
}

module.exports = {
    processOpenCommand,
    deleteGroupOperation,
    checkScheduledOperations,
    scheduleOpenOperation,
    calculateNextTime,
    horarioEmSegundos,
};
