/**
 * Revarifica manualmente todos os agendamentos pendentes.
 * Útil para testes ou comandos específicos.
 */
function checkScheduledOperations() {
    const schedule = loadData();
    if (!schedule || Object.keys(schedule).length === 0) return;

    const agora = moment();

    for (const [groupId, operacao] of Object.entries(schedule)) {
        if (!operacao?.fechar && !operacao?.abrir) continue;

        if (operacao.fechar && ehHoraDeExecutar(groupId, operacao.fechar)) {
            processarFechar(groupId, operacao.fechar, agora);
        }

        if (operacao.abrir && ehHoraDeExecutar(groupId, operacao.abrir)) {
            processarAbrir(groupId, operacao.abrir, agora);
        }
    }
}

function processarFechar(groupId, operacao, agora) {
    client.groupSettingUpdate(groupId, 'announcement');
    // delay(500); // mantido se desejar pausa entre operações
    // client.sendMessage(groupId, { text: `*Grupo fechado com sucesso 🔒*` });

    const proximo = calculateNextTime(operacao);
    operacao.nextDate = proximo.nextDate;
    operacao.timeRemaining = proximo.timeRemaining;
    saveData({ ...schedule, [groupId]: operacao });
    console.log(`[scheduler] Grupo ${groupId} fechado. Próximo: ${proximo.nextDate}`);
}

function processarAbrir(groupId, operacao, agora) {
    client.groupSettingUpdate(groupId, 'not_announcement');
    // delay(500);
    // client.sendMessage(groupId, { text: `*Grupo aberto com sucesso 🔓*` });

    const proximo = calculateNextTime(operacao);
    operacao.nextDate = proximo.nextDate;
    operacao.timeRemaining = proximo.timeRemaining;
    saveData({ ...schedule, [groupId]: operacao });
    console.log(`[scheduler] Grupo ${groupId} aberto. Próximo: ${proximo.nextDate}`);
}


